INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1028857-math208', 'stk-cortex', 'MATH 208', 'info', '{"desc": "جودة المقرر بشكل عام:\nانا مسجل المادة الترم هذا ولا خلصتها لسا , لكن بشكل عام المقرر سهل و مباشر ولا يحتاج فهم عميق عشان تحل !! أغلبها أشياء مكررة من ماث 002 و 101 و 102. لكن الترم هذا الدكاتره سيئين و ما عندهم شرح كويس و هذا يفسر الآفرجات الحالية .\nالمواضيع التي يغطيها المقرر :\n\nالمقرر يغطي المصفوفات بشكل أعمق من اللي أخذناه , و يعلمك عن الفكتورز في أكثر من بعد بشكل أفضل من اللي تم تدريسه في الـ 201 . و يتكلم بعمق عن فرع من الرياضيات اسمه الـ Differential Equations . هو أشوفه أكثر قسم من المنهج يحتاج مراعاة.\nالكتاب المستخدم للمقرر:\n\nالترم هذا 112 نستخدم كتاب سيء إلى أبعد حدّ ولا يفهم و أمثلته سطحية و طباعته سيئة .\nهذا غلافه :\n\nhttp://covers.openlibrary.org/b/id/135687-M.jpg\n\nالأترام اللي قبله الناس كانوا ياخذون المادة من هالكتاب :\nhttp://images.pearsoned-ema.com/jpeg/large/9780138141028.jpg\n\nو أكثر من شخص مدح لي الكتاب الأحمر هذا . بس ترتيب المتيريال يختلف هنا و هناك .\nالأسئلة والأمثلة المستخدمة في المقرر:\n\nسهله بشكل عام و صعب تخرج من الإطار العامل للفكرة الرئيسية . ممكن يتفننون في المشتقات و التكاملات , ما أعتقد يقدرون يلعبون في عوامل ثانية\nمدى فائدته في الناحية التطبيقية\n\nالكورس بشكل عام مختص بطلاب الكمبيوتر و الهندسة الصناعية . الكورس بشكل عام سهل لكنه ماهوب ممتع زي بقية كورسات الماث .\n\nمن الناحية التطبيقية فالكورس أفادني في مواد اخرى جالس أخذها حالياً لذلك أعتبره ممتاز في الجانب التطبيقي .\n\nموفقين 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/2", "user": "cortex", "ts": 1335447203000, "tid": 120617, "pn": 2}}', 1335447203000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1156367-math208', 'stk-a_dulaziz', 'MATH 208', 'info', '{"desc": "term 121\n\nالمواضيع التي يغطيها المقرر\n\nDifferential Equations & Linear Algebra\n\nالكتاب المستخدم للمقرر\n\nسيئ جدا إلى درجة أنه الأصدار الأول من عام 2002 مدري 2001\n\nما في له سلوشن\n\nمدرسنا الدكتور بدر الحميدي كان يستخدم أحياننا أمثل خارجية خصوصا بالدفرنشل يستخدم\nأمثلة كتاب 202\n\nبشكل عام المقرر سهل لاكن مشكلته مختلف عن 101 و 102\nأسلوب الدروس نوعا ما حفظ\n\nقوانين وتطبيق\n\nأغلب التركات الي تجي من مناهج قديمه يا أنتجريشن أو فاكتورايزيشن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/3", "user": "A_DULAZIZ", "ts": 1357437451000, "tid": 120617, "pn": 3}}', 1357437451000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1232568-math208', 'stk-gravity', 'MATH 208', 'info', '{"desc": "كورس رائع جدا…\n\n(الجزء الأول ) يتكلم عن كيفية حل معادلات الاشتقاق من الدرجة الاولى أو الثانية أو غيرها .\n(الجزء الثاني ) يتكلم عن حل المصفوفات والمحددات وخصائصها بشكل مفصل .\n(الجزء الثالث ) يتكلم عن eigenvalue وكيفية حلها بالمصفوفات وهي جدا مهمة .\n\nالكورس رائع جدا وسهل …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/5", "user": "Gravity", "ts": 1370594953000, "tid": 120617, "pn": 5}}', 1370594953000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1296482-math208', 'stk-computist', 'MATH 208', 'info', '{"desc": "Talks about Differential Equations + Linear Algebra\n\nHow to find solutions to differential equations of first, second and generally n order\nand applications to first order D.E in real life\n\nLinear Algebra: review about matrices determinants and more stuff about them + vector spaces R1, R2, R3 and generally Rn + applications of matrices in finding solutions to D.E\n\nThe course requires attention from the student from the first day\nIt requires a lot to understand but the majors are rather easier than the book problems", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/9", "user": "Computist", "ts": 1385710958000, "tid": 120617, "pn": 9}}', 1385710958000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1303279-math208', 'stk-the_doctor', 'MATH 208', 'info', '{"desc": "^^^\n\nانا قاعد اخذها ذا احين … تفاجأت الكل قال الكورس سهل وزي المويه لكن مو ذاك السهولة … والدليل الافرج حق المياجر . المادة يبيلها شغل شويتين . طبعا أسهل من ماث 201 … مع ذلك أحسها حلوة بالصيف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/14", "user": "the_doctor", "ts": 1386625038000, "tid": 120617, "pn": 14}}', 1386625038000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1373099-math208', 'stk-user2352', 'MATH 208', 'info', '{"desc": "هذا الكورس ماث260 انصح بدراسته في أي صيفي\nلأنه متوسط الصعوبة وإذا أنت فاهم ماث102 راح يسهل عليك الكثير خاصة الكورس سلف ستدي من وجهة نظري وما يفرق الدكتور كثير\nلأنك تحتاج طرق التكامل وكيفية حل المعادلات التفاضلية de\nوبقية الدروس يعيبها إن الحل طويل شوي ولكنها مو ذيك الصعبة\nأغلبها افهم الطريقة وطبقها على مسائل الكتاب والمياجر السابقة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/16", "user": "user2352", "ts": 1401264703000, "tid": 120617, "pn": 16}}', 1401264703000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1391628-math208', 'stk-s2012055', 'MATH 208', 'info', '{"desc": "المادة من أسهل مواد الماث, تعتمد:\n\n1- فهم الكونسبت جيدا\n\n2- ماث 102\n\n3- حل مسائل الكتاب والاولد اكزامز\n\nالمادة فيها جمع وطرح وفاكتورايزينغ كثيير\n\nالكتاب ممتاز الى حد ما, والمادة تعتمد على المدرس بس مو مررة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/18", "user": "s2012055", "ts": 1408614860000, "tid": 120617, "pn": 18}}', 1408614860000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422984-math208', 'stk-user8581', 'MATH 208', 'info', '{"desc": "math 260\nمقارنة بـ 102 و 101 و 201 فالكورس سهل و ينفع سيلف ستدي لو ماتوفقت في دكتور ممتاز\nلكن خصوصا بعد الميجر الأول الماتيريال يصير غثيث وحل المسائل يكون طويل\nالمياجر ريتين والفاينل ماتيريال بعد الميجر الثاني يكون ريتين والي قبل عليه 5 MCQ\nفحاول تنزل مع دكتور متساهل في التصحيح\n…\nالكتاب في الشباتر الاخيرة اشوفه سيئ واحيانا يطول السالفة وهي قصيرة لكن اذ مافهمت الدرس عندك اليوتيوب … ولو نزلت عندك دكتور ممتاز راح يسهل عليك المادة ومايبقى عليك الا حل بعض مسائل الكتاب\nهالكورس لمفروض اقل قريد تطلع فيه b+ بشرط ان توزيع القريدات يكون عادل ومنطقي عكس سمستر 142 كان التوزيع سيئ\n!!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/19", "user": "user8581", "ts": 1437935763000, "tid": 120617, "pn": 19}}', 1437935763000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1431860-math208', 'stk-ak-95', 'MATH 208', 'info', '{"desc": "ترم 151 ، هذا الكتاب :\n\nالمنهج سهل بشكل عام ، لكن الكتاب سيء جدا في الشرح وتسلسل الأفكار .\nالآن أعاني في شابتر 4 (Vector spaces) جدا ، عرض القواعد بشكل ملخبط ومكرر ومختلف …\n\nمن الأخير ، Patrick هو الحل 🙂\nhttps://www.youtube.com/user/patrickJMT", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/20", "user": "AK-95", "ts": 1446476436000, "tid": 120617, "pn": 20}}', 1446476436000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1433388-math208', 'stk-user9929', 'MATH 208', 'info', '{"desc": "الله يجزاك خير اخوي ويعطيك العافية\nوضعي ما يسمح انزل كورسين بعض في نفس الترم\n\nCE 318 Numerical & Statistical Methods in Civil Engineering (2-3-3)\nIntroduction to numerical methods; error analysis; solution of system of linear and nonlinear\nequations; numerical integration; numerical solutions of ordinary differential equations; curve\nfitting and interpolation; statistical methods, descriptive statistics, probability distributions,\nanalysis of variance and regression; introduction to linear programming and optimization\nproblems; development and application of computer programs to case studies derived from civil\nengineering practices.\nPrerequisite: ICS 103 (or e quivalent) , MATH 260", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/25", "user": "user9929", "ts": 1447604912000, "tid": 120617, "pn": 25}}', 1447604912000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1458092-math208', 'stk-mkd', 'MATH 208', 'info', '{"desc": "Term 153\n\nخذته مع العراجي ABDALLAH LARADJI\n\nالكورس رهيب وحق قريد … تجيب أقل من B+ بأفقع وجهك 🙂 بس يحتاج متابعة وزي ما قالوا اللي فوق تحتاج انتقريشن بشكل متوسط\n\nمنب متكلم عن الماتيريال ، بشكل عام مفهوم وحلو\n\nالمشكلة الوحيدة هذي اخر شابتر بالكورس شابتر 7 ، خصوصا 7.5 !! تقريبا 40% من الفاينل كان عن هذا الشابتر !! جدا مهم والصراحة أعتبره أصعب شابتر وتحتاج تحل أكبر عدد تقدر عليه ( حرفيا ) !!\n\nركز عليه قبل الفاينل ولو تحل أسئلة قديمة وتوريها دكتورك قبل الفاينل أفضل وأفضل عشان تتأكد انك ما تجيب العيد ، لأن خطا بسيط جدا في حل سؤال يخلي حلك غلط في غلط 🙂\n\nأنصحك تاخذه مع العراجي بدون ما تفكر . تصحيح رهيب وشرح جيد و جدا جدا حبيب ( كيف السجع ) =)\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/27", "user": "MKD", "ts": 1474291509000, "tid": 120617, "pn": 27}}', 1474291509000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1492309-math208', 'stk-breaktheunbreakable', 'MATH 208', 'info', '{"desc": "مادة حلوة تتابع فيها أضمن لك تحصل فيها B+ بالراحة. المادة عبارة عن خليط بين Math 002 و Math 102 وتتعلموا أشياء جديدة وكيف تستعمل اللي تعلمته في الماث لتحل أنظمة دفرنشل انكويشنز.\nالكورس في الصيف مشابه للترم العادي، المادة ما يقدروا يصعبوها كثير لأن ما بها تركات بس تطبيق للكونسبت.\nأعطي المادة حقها ووقتها لا تعاملها كأنها مادة ثانوية، ذا الشيء بينزل درجاتك فيها.\nأنصح بالمادة إذا كنت بتاخذها إلكتف.\nتقدر تذاكر من نوتات الدراجي أو التتار، الكتاب بعض الأحيان عبيط ويشرح أشياء ما لها داعي.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/30", "user": "BreakTheUnbreakable", "ts": 1526272546000, "tid": 120617, "pn": 30}}', 1526272546000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522207-math208', 'stk-user11151', 'MATH 208', 'info', '{"desc": "عبدالإله قادري - ١٩٢\n\nباختصار المادة سهلة جدا جدا وسهل تحصل فيها درجة ممتازة بشرط تعطيها حقها.\nنصيحة لا تأجلها وتتأخر خذها مباشرة بعد ما تخلص موا الرياضيات اللي عندك عشان ما تطلع من الجو.\n\nإذا نزلتها عند عبدالإله قادري، فأبشرك هو شخص عسل ورائع ولكن خله يشوف فيك الحرص والاهتمام.\nاطبع المذكرات اللي يرسلها فيها كل شي تحتاجه -قصيرة ماهي طويلة- ووقت المحاضرة خطط عشان تفهم إذا رجعت لها.\n\nذاكر للاختبارات زين وإذا جاط وقت الميجر ما تحتاج إلا أنك تحل اختبارات قديمة وبكذا تقدر تجيب درجة كاملة بإذن الله.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/31", "user": "user11151", "ts": 1590008175000, "tid": 120617, "pn": 31}}', 1590008175000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533225-math208', 'stk-posty', 'MATH 208', 'info', '{"desc": "Term 211\n\nالمادة الكونسبت حقها نوعا ما جديد مقارنة ب الكورسات الي قبل، الكورس يجمع مابين الديفرنشل ايكويشنز و اللينير الجبرا (لا يغرك اسم لينير الجيبرا تراها اصعب جزء في الكورس) بس بالمجمل المادة مو صعبه لاكن تبقى ماث ولازم تعطيها حقها، هي اسهل من ماث ٢٠١، اما مقارنة ب ١٠١-١٠٢ صعبه تحديد صعوبتها بينهم، الكورس ميزته دروسه قليله مقارنة بالكورسات الي قبل، والافكار محاولين مايتعمقون فيها بحكم انها كونسبت جديد\n\nالاختبارات مع هذا الترم بادين يحولونها لاختياري بدال الريتن وللاسف مع كذا الكورس راح يصير ظلم كبير، الميد كان ٤ اسئلة اختياري و ٤ رتن وللاسف سؤال الاختياري الواحد كان عليه ٣ درجات اما الريتن كانت بين ٣-٤ درجات وعليها بارشل بحكم انها ريتن، والفاينل كان كله اختيارات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-208-introduction-to-differential-equations-linear-algebra/120617/32", "user": "Posty", "ts": 1640990048000, "tid": 120617, "pn": 32}}', 1640990048000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p539769-math208', 'stk-user3193', 'MATH 208', 'info', '{"desc": "الاسئلة كانت صعبة صراحة وانا كنت متوقع لان افرج الميجر الثاني كان السبب لانه مرتفع جدا\n\nولكن عسى الدكتور يتساهل بالتصحيح\n\nلاني احل احل احل ولما اوصل بالاخير يتوهق البطل\n\nالله يستر\n\nوعلى فكرة الي ركز بالاختبار راح يعرف انه شمل ماث 101 و 102 و 201 و 260\n\nيعني 4 في 1 هههههههههههه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-260/83289/10", "user": "user3193", "ts": 1265587913000, "tid": 83289, "pn": 10}}', 1265587913000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1432146-math208', 'stk-nostalgia', 'MATH 208', 'info', '{"desc": "بم ان الماتيريال اخذناه بسرعة … هذي بعض الاسئلة المهمة من تشابتر 4 قال بخاري ان بيجي مثلها بالضبط\nملاحظة: اتمنى ان ذي الاسئلة مايدري عنها احد سواء بخاري او الدكتور الثاني عشان ما تسير مشاكل وكذا …\n4.1 --- سؤال 8+9+15+19+25+29+30\n4.2 --- سؤال 4+15+19 … سؤال 19 100% بيجي مثله بالاختبار\n4.3 --- سؤال 2+6+9 … سؤال 9 فكرته مهمة جدا\n4.4 --- سؤال 2+4+9+14+20\n\nوهذا سؤال مهم بيجي 100% واحد زيه : Find a basis :\n2x + y + 0w + z + g + k = 0\nx + y + 0z + 0w + g + k = 0\n3x + 2y + 0z + w + 2g + 2k = 0", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-260-major-ii/170682/5", "user": "Nostalgia", "ts": 1446670415000, "tid": 170682, "pn": 5}}', 1446670415000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1458072-math208', 'stk-superson1c', 'MATH 208', 'info', '{"desc": "حتى الان اشوف تنزل\nGeol201\nEe204\nMath260\n+ماده عربي او اسلامي او الي قالها خالد Are\nهذي ١٢ ساعه وقريداتها سهله (مع شده الحيل طبعا)\n--------------\n\n١٢ ساعه تكفي وزوود انت في حاله خطر ولازم تنزل قليل عشان تركز عالمواد وتطلع بمعدل\n\n+ما انصح تنزل ماثين خصصوصا201 اصعب من 260", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-5/174706/22", "user": "SUPERSON1C", "ts": 1474285549000, "tid": 174706, "pn": 22}}', 1474285549000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p872376-math208', 'stk-amat_24', 'MATH 208', 'info', '{"desc": "😆 😆 😆 😆 😆\n\nارحمني يا هوكو… جبت ابو العيد!!!!\n\nاولا ربطت الكمبيوتر والماث… الsoftware engineering ما ياخذو الا 3 كورسات ماث بس،، وينسو ابوها بعدين (مع انه عندهم arithmetics… بس هذي كلام فاضي ماهي ماث) ، اما بالنسبة للcomputer engineering ياخذو ال3 الاولى بالاضافة الا math260 يعني ما ياخذو حتى 202،، زيكم يا سستماوية\nاما المكنكل والالكتركل،، ياخذو 5 كورسات ، بالنسبة للمكنكل الثلاثة الاولى تطبق فيها الين ما تتخرج… الباقية تمر على خفيف… مدري الالكتركل كيف نظامهم بس اسمع انهم يتعمقو في الlaplace transform واشباهها\n\nثاني حاجة،،\n“ما تحب تتعامل مع البشر” بالنسبة لهندسة البرمجيات على الاقل،، تقريبا كل بروجكتاتهم جماعية واعتقد بعضها تكون على مدار السمستر كامل\nاما المكنكل،، تذاكر لوحدك،، تشتغل لوحدك،، تسوي البروجكت لوحدك،، تبكي عليه لوحدك 😭… فيه جماعية لكن الاغلب فردي 🥊\n^^^\nالكلام هذا بالنسبة لظروف الدراسة… بالنسبة للعمل، اشوف المكنكل يحتك بالجميع يعني ممكن حتى تشرف على عمال او تكنشنز وتناقش المشاريع مع مهندسين من تخصصات ثانية الخ\n\nبس صدقت في حاجة،، كثيرين يروحو الصناعة لمجرد انها هندسة… بلا ميول معين\nوالبعض يحول لها من المكنكل بعد الصعوبة اللي واجهها… وفي هذي الحالة يسمى التخصص “مخرج كلية الهندسة” لانه ما حيلاقي الامور سهلت كثير ويحول ادارة 😁\n^^\nلاحد سستماوي يزعل 🌹 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/109878/18", "user": "amat_24", "ts": 1311121248000, "tid": 109878, "pn": 18}}', 1311121248000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p520960-math208', 'stk-ise-26', 'MATH 208', 'info', '{"desc": "^\n\nالماده هذي 4 ساعات + لاب\n\nوانا صراحه ما انصحك تنزلها … لانها اصلا ماده ثقيلة\nوفوق هذا كله … ما تفتح لك اي شي\n\nيعني خليها بدري عليها … فيه مواد اهم منها خذها عشان تفيدك بالمواد الثانيه\n\nوانا من رايي نزل math260 اذا ما كنت منزل الكورس هذا للحين\nلانه بيفيدك باكثر من شي … وغير هذا كورس موب ثقيل و 3 ساعات\nواحسن لك بكثير من cise302\n\nاو شف لك cise301 ماده 3 ساغات وحلوه واخف بكثير من cise302\nولا فيها لاب\n\nبالتوفيق يارب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/092-ise/80839/245", "user": "ISE-26", "ts": 1263125119000, "tid": 80839, "pn": 245}}', 1263125119000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p472663-math208', 'stk-nice_one', 'MATH 208', 'srcP', '{"html": "تشابتر ون<br><br>​<span data-fid=\"stk-f472663-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f472663-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f472663-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f472663-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f472663-4\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f472663-5\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f472663-6\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f472663-7\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f472663-8\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f472663-9\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f472663-10\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f472663-0": {"name": "sect1-1.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-1": {"name": "sect1-2.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-2": {"name": "sect1-4.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-3": {"name": "sect1-5.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-4": {"name": "sect1-6.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-5": {"name": "sect3-1.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-6": {"name": "sect3-2.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-7": {"name": "sect3-3.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-8": {"name": "sect3-4.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-9": {"name": "sect3-5.pdf", "v": "data:application/pdf;base64,"}, "stk-f472663-10