INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p436535-math208', 'stk-user2685', 'MATH 208', 'srcP', '{"html": "أبشروا بعزكم 🙂<br><br>​<span data-fid=\"stk-f436535-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f436535-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f436535-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f436535-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f436535-4\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f436535-5\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f436535-6\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f436535-7\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f436535-8\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f436535-9\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f436535-10\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f436535-11\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f436535-12\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f436535-0": {"name": "Ch.1.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/41fd984e2626b130baf4ee38628979a6e0dbda99f02485cf20b3c5e36cd18f6c"}, "stk-f436535-1": {"name": "Ch.2.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/ec2eeb7f332d64474e30149473d7d767400c8367029982c786061377403b198c"}, "stk-f436535-2": {"name": "Ch.3.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a396abe14d35eaf4b1a6f372670d059df93a8f2d57cf582d96cb0cf1aa1445fd"}, "stk-f436535-3": {"name": "Ch.4.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/f